#include <chrono>
#include <iomanip>
#include <iostream>
#include "mesh/cubed_sphere/hermite_boundary_sampler.hpp"
#include "mesh/cubed_sphere/composite_checkpoint.hpp"
using Clock=std::chrono::steady_clock;
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=3)throw std::runtime_error("checkpoint source_tag");auto snapshot=cubed_sphere::CompositeCheckpoint::Read(argv[1],argv[2]);cubed_sphere::CompositeDifference grid(snapshot.mesh,4,snapshot.radial_interface_stencils);if(grid.active.size()>50000)throw std::runtime_error("bounded50000");cubed_sphere::ScriSurface surface(grid,22,snapshot.scri_radial_points);std::vector<Real> metric(22*grid.count,0),beta(3*grid.count,0),beta_boundary(surface.rows.size()*3,0);for(size_t p=0;p<grid.active.size();++p){for(int f=0;f<22;++f)metric[f*grid.count+grid.active[p]]=snapshot.fields[22*p+f];for(int i=0;i<3;++i)beta[i*grid.count+grid.active[p]]=snapshot.shift_warm_start[3*p+i];}auto start=Clock::now();cubed_sphere::HermiteBoundarySampler sampler(surface);Real construction=std::chrono::duration<Real>(Clock::now()-start).count(),checksum=0;std::cout<<std::setprecision(17)<<"{\"cells\":"<<grid.active.size()<<",\"rows\":"<<surface.rows.size()<<",\"construction_seconds\":"<<construction<<",\"repetitions\":[";
 for(int repeat=0;repeat<3;++repeat){auto t0=Clock::now();auto p22=sampler.Prepare(metric,snapshot.boundary_fields,22,repeat+1);auto t1=Clock::now();auto p3=sampler.Prepare(beta,beta_boundary,3,repeat+1);auto t2=Clock::now();for(size_t p=0;p<surface.rows.size();++p){auto u=sampler.Sample(p,p22);checksum+=u.value[0]+u.d[0][0]+u.dd[0][0][0];}auto t3=Clock::now();for(size_t p=0;p<surface.rows.size();++p){auto u=sampler.Sample(p,p3);checksum+=u.value[0]+u.d[0][0]+u.dd[0][0][0];}auto t4=Clock::now();if(repeat)std::cout<<',';std::cout<<"{\"Prepare22\":"<<std::chrono::duration<Real>(t1-t0).count()<<",\"Prepare3\":"<<std::chrono::duration<Real>(t2-t1).count()<<",\"Samples22\":"<<std::chrono::duration<Real>(t3-t2).count()<<",\"Samples3\":"<<std::chrono::duration<Real>(t4-t3).count()<<'}';}
 std::cout<<"],\"checksum\":"<<checksum<<",\"beta_boundary_synthetic_zero_for_timing_only\":true,\"no_evolution\":true}\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
